import React, {useState} from 'react';
import {EmailList} from './Components/EmailList';
import {EmailDetail} from './Components/EmailDetail';
import {ComposeEmail} from './Components/ComposeEmail';


export const app: React .FC =() => {
 const [emails, setEmails] = useState ([
    {id: 1, subject: 'Hello world', sender : 'example@example.com', body: 'this is a test Email.'},
    {id: 2, subject: 'React is awesome!', sender: 'react@react.com', body: 'Let\'s  build something amaizing.'},
 ]);

 const [SelectedEmail, setSelectedEmail] = useState (null);

 const handleselectEmail = (email) => {
    setSelectedEmail(email);
 };

 const handlesendEmail = (subject , body ) => {
    const newEmail = {
        id: emails.length + 1,
        subject,
        sender : 'me@example.com',
        body,
    };
    setEmails([...emails, newEmail]);
 };
 return (
    <div className = "app">
        <h1>EmailLify</h1>
        <ComposeEmail onsend ={handlesendEmail} />
        <EmailList emails = {emails} onSelectEmail = {handleselectEmail} />
        <EmailDetail email = {SelectedEmail} />
    </div>
 );
};
